/**
 * Stepper (D105 (12)): [label] above, then minus, [value] (label size, tabular, centred in the widest value of
 * [range]), plus; each change calls [onChange] and TalkBack hears [spoken] of the new value („13 Wiederholungen“).
 * [step] is the amount of one press (5 for minutes in fives); [spoken] is composable, so it may use
 * pluralStringResource.
 */
@Composable
fun SbStepper(
    label: String,
    value: Int,
    onChange: (Int) -> Unit,
    range: IntRange,
    modifier: Modifier = Modifier,
    step: Int = 1,
    spoken: @Composable (Int) -> String = { "$it $label" },
) {
    require(step > 0) { "SbStepper: step > 0" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val style = ty.label.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val measurer = rememberTextMeasurer()
    val shown = sbFormatCount(value)
    val widest = sbFormatCount(range.last)
    val room = with(LocalDensity.current) {
        remember(widest, style, measurer) { measurer.measure(widest, style).size.width }.toDp()
    }
    val said = spoken(value)
    Column(modifier, verticalArrangement = Arrangement.spacedBy(t.space.s1)) {
        Text(label, style = ty.label, color = c.text)
        Row(verticalAlignment = Alignment.CenterVertically) {
            SbIconButton(
                SebaroIcons.Outline.Minus,
                m.stepperLess(label),
                onClick = { onChange((value - step).coerceIn(range)) },
                enabled = value > range.first,
            )
            Box(
                Modifier
                    .widthIn(min = room + t.space.s4)
                    .clearAndSetSemantics {
                        liveRegion = LiveRegionMode.Polite
                        contentDescription = said
                    },
                contentAlignment = Alignment.Center,
            ) {
                Text(shown, style = style, color = c.text, softWrap = false)
            }
            SbIconButton(
                SebaroIcons.Outline.Plus,
                m.stepperMore(label),
                onClick = { onChange((value + step).coerceIn(range)) },
                enabled = value < range.last,
            )
        }
    }
}
